mapper.select:
WITH selected AS MATERIALIZED (
SELECT v.id,v.content,v.metadata,v.embedding,k.name
FROM reading_vectors v JOIN reading_kb k ON v.metadata->>'kbId'=k.id
AND v.metadata->>'generation'=k.generation
WHERE k.status='READY' AND k.model_id=#{modelId} AND k.dimensions=#{dimensions}
AND k.id IN
#{id}
)
SELECT id::text AS id,'BOOK' AS type,name AS title,
COALESCE(metadata->>'location','正文') AS location,'' AS url,content AS text
FROM selected ORDER BY embedding <=> CAST(#{vector} AS vector) LIMIT #{limit}

WITH selected AS MATERIALIZED (
SELECT v.id,v.embedding FROM reading_vectors v JOIN reading_book_chunk c ON v.id=c.vector_id
AND v.metadata->>'kbId'=c.kb_id AND v.metadata->>'generation'=c.generation
WHERE c.kb_id=#{kbId} AND c.generation=#{generation}
)
SELECT id::text AS id FROM selected ORDER BY embedding <=> CAST(#{vector} AS vector) LIMIT #{limit}
